function product(){const groups=[["01","Клиенты и заявки","Единая база обращений и контактов: история общения и следующий шаг не теряются.","Создание заявок и этапы обработки","Карточки клиентов и контакты","Источники обращений и статусы воронки","Связь заявки с клиентом и объектом"],["02","Объекты и задачи","Рабочая структура проекта с ответственными, сроками и связями между сущностями.","Создание объектов и статусы выполнения","Привязка клиента и исходной заявки","Планирование задач и сроков","Напоминания по задачам и активным объектам"],["03","Сметы и коммерческие предложения","Расчёт стоимости работ и затрат с формированием экономики КП.","Строки работ: объём, цена и себестоимость","Учёт скидки, прямых и накладных затрат","Налоговый резерв и итоговая экономика","Расчёт выручки, затрат, прибыли и маржи"],["04","Производство и ПИ","Контроль исполнения на объекте: планы, смены и сравнение плановых и фактических показателей.","Производственные планы по объектам","Фиксация смен, бригады и выполненных объёмов","Учёт простоев и отклонений от норм","Прогноз остатка работ при достаточных данных","Предупреждения о просрочках и повторяющихся отклонениях"],["05","Инженерный расчёт","Инженерный расчёт и работа с ведомостями в отдельном тарифном контуре.","Инженерный расчёт объекта","Импорт Excel-ведомостей","Ручная проверка сопоставления позиций","Проверка единиц измерения перед заменой данных"],["06","Финансы и экономика","Денежные операции и финансовые показатели на основании сохранённых данных.","Учёт поступлений и расходов","Категории расходов и статусы оплаты","Экономика объектов: договор, поступления и затраты","Финансовые сводки и предупреждения о качестве данных"],["07","Поиск заказов","Ручной поиск потенциальных заказов в открытых источниках с сохранением первоисточников.","Поисковые сценарии Web, Telegram, Avito и тендеры","Импорт списков CSV/TXT","Нормализация ссылок и удаление дублей","Предварительная оценка релевантности","Передача выбранного заказа в воронку CRM"],["08","Браузер, отчёты и настройки","Инструменты для работы с данными и приложением в едином интерфейсе.","Встроенный браузер для веб-источников","Отчёты по данным CRM","Быстрый переход по разделам","Локальные настройки и PIN-защита"],["09","Локальные данные и резервные копии","Приложение рассчитано на локальную работу под Windows.","Локальная база SQLite","Без обязательного облачного аккаунта","Создание и восстановление резервной копии","Локальная проверка лицензии без интернет-запроса","Device ID и цифровая подпись Ed25519"]];return '<main class="inner-page product-detail-page"><section class="product-detail-hero section-pad"><div class="section-kicker"><span>СКОЛ / PRODUCT 001</span><span>WINDOWS DESKTOP SOFTWARE</span></div><div class="product-detail-grid"><div><p class="eyebrow">BUSINESS MANAGEMENT SYSTEM</p><h1>СКОЛ <em>CRM.</em></h1><p class="product-detail-lead">Система управления строительным бизнесом — клиенты, заявки, объекты, сметы, производство, финансы и поиск заказов в одном локальном приложении.</p><div class="product-detail-actions"><a class="button button-red" href="/tariffs">Тарифы и условия <span>↗</span></a><a class="button button-outline" href="/download">Скачать / обновления <span>↓</span></a></div><div class="product-detail-facts"><span><b>WINDOWS 10 / 11</b><small>Платформа</small></span><span><b>LOCAL SQLITE</b><small>Хранение данных</small></span><span><b>OFFLINE</b><small>Проверка лицензии</small></span></div></div><div class="product-detail-visual"><div class="detail-glow"></div><div class="detail-app-window"><div class="detail-app-top"><span>● ● ●</span><b>СКОЛ / РАБОЧЕЕ ПРОСТРАНСТВО</b><small>LOCAL</small></div><div class="detail-app-body"><aside><b>S</b><i></i><i></i><i></i><i></i><i></i></aside><div class="detail-app-content"><small>ОБЗОР БИЗНЕСА</small><strong>Бизнес начинается<br>с ясной картины.</strong><div class="detail-metrics"><i></i><i></i><i></i></div><div class="detail-rows"><i></i><i></i><i></i><i></i></div></div></div></div><span class="detail-visual-caption">PRODUCT INTERFACE / ILLUSTRATIVE MOCKUP</span></div></div></section><section class="product-summary section-pad"><div><span class="eyebrow">ЧТО ЭТО ЗА ПРОГРАММА</span><h2>От обращения<br>до <em>выполненного объекта.</em></h2></div><div><p>СКОЛ CRM объединяет ключевые процессы подрядной компании в одном настольном приложении. Вместо разрозненных таблиц пользователь ведёт клиентов, заявки, объекты, задачи и производственные данные в связанной системе.</p><p>Программа рассчитана на локальную работу под Windows. Основная база SQLite находится на компьютере; для ежедневной работы и проверки лицензии постоянное подключение к интернету не требуется. Веб-поиск и встроенный браузер, разумеется, требуют сети.</p></div></section><section class="product-capabilities section-pad"><div class="section-kicker"><span>01 / CAPABILITIES</span><span>ВОЗМОЖНОСТИ ПРОГРАММЫ</span></div><div class="capabilities-heading"><h2>Рабочие инструменты.<br><em>В одном пространстве.</em></h2><p>Состав доступных модулей зависит от тарифа. Ниже описаны разделы и функции исходной CRM.</p></div><div class="capability-grid">'+groups.map(g=>'<article class="capability-card"><div class="capability-card-top"><span>'+g[0]+' / MODULE</span><b>↗</b></div><h3>'+g[1]+'</h3><p>'+g[2]+'</p><ul>'+g.slice(3).map(x=>'<li><i>✓</i>'+x+'</li>').join("")+'</ul></article>').join("")+'</div></section><section class="product-workflow section-pad"><div><span class="eyebrow">CONNECTED WORKFLOW</span><h2>Данные не должны<br><em>теряться между этапами.</em></h2><p>Заявка может стать объектом, объект использует расчёт и производственный план, а фактические операции и затраты помогают оценивать результат. Пользователь сохраняет контроль над переходами и подтверждает важные действия.</p></div><div class="workflow-steps"><div><span>01</span><b>Обращение</b><small>Клиент и заявка</small></div><div><span>02</span><b>Подготовка</b><small>Объект, смета и КП</small></div><div><span>03</span><b>Исполнение</b><small>План, смены и факт</small></div><div><span>04</span><b>Контроль</b><small>Финансы и отчёты</small></div></div></section><section class="product-tariff-summary section-pad"><div><span class="eyebrow">ACCESS / EDITIONS</span><h2>Три уровня<br><em>возможностей.</em></h2><p>Разделы PRO и BUSINESS открываются по подписанному лицензионному ключу. Точные разрешения сверяются с матрицей лицензирования CRM.</p></div><div class="edition-summary"><article><b>START</b><span>База работы</span><p>Клиенты, заявки, объекты, задачи и рабочее пространство.</p></article><article><b>PRO</b><span>Управление исполнением</span><p>START + инженерный расчёт, финансы, производство и отчёты.</p></article><article><b>BUSINESS</b><span>Расширенный контур</span><p>PRO + радар заказов, расширенная аналитика, инженерные планы и браузер.</p></article><a class="text-link" href="/tariffs">Сравнить тарифы и запросить условия ↗</a></div></section><section class="product-technical section-pad"><div class="section-kicker"><span>02 / TECHNICAL DETAILS</span><span>ТРЕБОВАНИЯ И ОГРАНИЧЕНИЯ</span></div><div class="technical-grid"><article><span>ПЛАТФОРМА</span><h3>Windows 10 / 11</h3><p>Настольное приложение Electron x64. Установщик публикуется отдельно в релизах CRM.</p></article><article><span>ХРАНЕНИЕ</span><h3>Локальная SQLite</h3><p>Рабочая база хранится на компьютере. Перед обновлением рекомендуется сделать резервную копию.</p></article><article><span>ЛИЦЕНЗИЯ</span><h3>Ed25519 / Device ID</h3><p>Подписанный ключ привязан к идентификатору устройства. Проверка подписи и тарифа выполняется локально.</p></article><article><span>СЕТЬ</span><h3>Не обязательна для базовой работы</h3><p>Локальные сценарии и активация работают без сети. Веб-поиск и встроенный браузер требуют интернет-соединения.</p></article></div><div class="product-limitations"><h3>Что важно учитывать</h3><ul><li>Офлайн-лицензию нельзя удалённо отозвать; при замене компьютера менеджер выпускает новый ключ для нового Device ID.</li><li>Срок updatesUntil отображается в лицензии, но в текущей реализации не блокирует обновления программы.</li><li>Офлайн-приложение не может централизованно контролировать количество активных устройств по одной покупке.</li><li>Поиск заказов выполняется вручную; полнота выдачи зависит от источников. Это не гарантия автоматического получения заказов.</li></ul></div></section><section class="product-final-cta section-pad"><div><span class="eyebrow">SKOL CRM / PRODUCT 001</span><h2>Посмотрите тарифы<br><em>и обсудите подключение.</em></h2><p>Подключение оформляется через менеджера. Онлайн-оплата и автоматическая выдача ключа не подключены.</p></div><div><a class="button button-red" href="/tariffs">Запросить условия ↗</a><a class="text-link" href="/activation">Как активировать программу →</a></div></section></main>'}

function keyField(){return '<section class="key-field section-pad"><div class="key-field-content"><span class="eyebrow">SKOL / LICENSE ENGINE</span><h2>Ваш доступ.<br><em>Ваш ключ.</em></h2><p>Каждая лицензия подписывается цифровой подписью и привязывается к устройству. Программа проверяет её локально — без обращения к серверу.</p><div class="key-token-demo"><span>SKOL1.</span><i>eyJwcm9kdWN0IjoiU0tPTF9DUk0i...</i><b>✓ SIGNED</b></div></div><div class="key-visual" aria-hidden="true"><div class="key-visual-shadow"></div><div class="key-visual-plate"><span>SKOL / LICENSE</span><strong>01</strong><div class="key-visual-chip">ED25519</div><small>DEVICE BOUND · LOCAL CHECK</small></div><div class="key-visual-orbit key-orbit-a"></div><div class="key-visual-orbit key-orbit-b"></div></div></section>'}
function tariffs(){
  const comparisonRows=[
    {label:"Клиенты, заявки, объекты и задачи",base:true},
    {label:"Рабочее пространство",base:true},
    ...tariffFeatures.map(feature=>({label:feature.name,id:feature.id}))
  ];
  const priceLabel=plan=>plan.price===null||plan.price===undefined?"Стоимость по запросу":new Intl.NumberFormat("ru-RU").format(plan.price)+" ₽";
  return '<main class="inner-page tariffs-page"><section class="inner-hero tariff-hero section-pad"><div class="section-kicker"><span>СКОЛ / ЛИЦЕНЗИИ</span><span>PRESETS + CUSTOM / ACCESS SYSTEM</span></div><div class="tariff-hero-grid"><div class="tariff-hero-copy"><p class="eyebrow">КОНФИГУРАЦИЯ РАБОЧЕЙ СИСТЕМЫ</p><h1>Выберите свой<br><em>уровень управления.</em></h1><p class="tariff-hero-lead">Выберите готовый тариф или соберите собственный набор модулей. Состав лицензии фиксируется в подписанном ключе и проверяется CRM локально.</p><a class="button button-red" href="#tariff-cards">Сравнить возможности <span>↓</span></a><div class="tariff-hero-meta"><span><i class="live-dot"></i> ЛОКАЛЬНАЯ ЛИЦЕНЗИЯ</span><span>WINDOWS / DESKTOP</span><span>PRESETS + CUSTOM</span></div></div><div class="tariff-hero-scene" aria-label="Объёмная визуализация лицензий СКОЛ"><div class="tariff-scene-grid"></div><div class="tariff-scene-orbit orbit-one"></div><div class="tariff-scene-orbit orbit-two"></div><div class="tariff-scene-core"><span>SKOL</span><strong>CRM</strong><i>LICENSE / V2</i></div><div class="tariff-scene-chip chip-start"><small>01 / BASE</small><b>START</b></div><div class="tariff-scene-chip chip-pro"><small>02 / ADVANCED</small><b>PRO</b></div><div class="tariff-scene-chip chip-business"><small>03 / FULL</small><b>BUSINESS</b></div><div class="tariff-scene-coordinates">55°45′N<br>37°37′E</div></div></div></section>'+keyField()+'<section class="tariff-cards section-pad" id="tariff-cards"><div class="section-kicker"><span>01 / ГОТОВЫЕ ТАРИФЫ</span><span>ВЫБЕРИТЕ СТАРТОВУЮ КОНФИГУРАЦИЮ</span></div><div class="tariff-intro-row"><h2>Готовые планы.<br><em>Без лишних функций.</em></h2><p>Каждый тариф состоит из базового рабочего пространства и конкретных модулей. Состав и цены управляются через локальный License Manager.</p></div><div class="tariff-grid">'+plans.map((p,i)=>'<article class="tariff-card tariff-card-3d '+p.color+'" id="'+p.id.toLowerCase()+'" data-tariff-card style="--card-index:'+i+'"><div class="tariff-card-top"><span>0'+(i+1)+' / '+p.id+' EDITION</span><b>'+(i===0?'◌':i===1?'◈':'✳')+'</b></div><div class="tariff-card-orb tariff-orb-'+p.id.toLowerCase()+'"><i></i><i></i><i></i><span>'+String(i+1).padStart(2,"0")+'</span></div><div class="tariff-card-heading"><h2>'+p.id+'</h2><span>'+String(p.title||p.name||"CUSTOM PLAN").toUpperCase()+'</span></div><h3>'+p.title+'</h3><div class="tariff-price">'+priceLabel(p)+'</div><p>'+p.desc+'</p><div class="tariff-divider"></div><span class="list-label">СОСТАВ ЛИЦЕНЗИИ</span><ul>'+p.features.map(feature=>'<li><i>↗</i>'+feature+'</li>').join("")+'</ul><div class="tariff-card-bottom"><span>'+p.note+'</span><a class="button '+(p.color==="red"?"button-red":p.color==="dark"?"button-light":"button-outline")+'" href="#tariff-builder" data-plan="'+p.id+'">Выбрать '+p.id+' <b>↗</b></a></div><div class="tariff-card-index">SKOL / 0'+(i+1)+'</div></article>').join("")+'</div></section>'+tariffBuilder()+'<section class="comparison-section section-pad"><div class="section-kicker"><span>03 / МАТРИЦА ДОСТУПА</span><span>СОСТАВ ТАРИФОВ</span></div><h2>Модули<br><em>по уровням доступа.</em></h2><div class="comparison-table" id="tariff-comparison" aria-label="Сравнение возможностей тарифов"><div class="comparison-row comparison-head"><span>ВОЗМОЖНОСТЬ</span>'+plans.map(plan=>'<b>'+plan.id+'</b>').join("")+'</div>'+comparisonRows.map(row=>'<div class="comparison-row" data-comparison-row><span>'+row.label+'</span>'+plans.map(plan=>{const enabled=row.base||plan.featureIds.includes(row.id);return '<b data-plan-col="'+plan.id+'" class="'+(enabled?"yes":"no")+'">'+(enabled?"✓":"—")+'</b>'}).join("")+'</div>').join("")+'</div><p class="comparison-note">Сравнение строится по реальному каталогу модулей СКОЛ CRM. Функции без отдельной проверки в приложении не предлагаются как самостоятельные платные опции.</p></section><section class="tariff-request section-pad" id="tariff-request"><div class="section-kicker"><span>04 / ПОДКЛЮЧЕНИЕ</span><span>ЗАПРОС ЛИЦЕНЗИИ</span></div><div class="tariff-request-grid"><div><span class="eyebrow">NEXT STEP / ACTIVATION</span><h2>Определились<br><em>с конфигурацией?</em></h2><p>Оставьте контакт и выбранный состав. Заявку можно передать менеджеру как JSON и импортировать в License Manager. Ключ подписывается локально закрытым ключом владельца продукта.</p><a class="text-link" href="/activation">Посмотреть процесс офлайн-активации ↗</a></div><form class="contact-form tariff-form" id="tariff-form"><div class="tariff-form-top"><span>LICENSE REQUEST</span><b><i class="live-dot"></i> READY</b></div><p class="tariff-selected-status" id="tariff-selected-status" aria-live="polite">Выберите готовый тариф или соберите свою конфигурацию</p><label>Выбранный тариф<select name="plan" id="plan-select">'+plans.map(plan=>'<option value="'+plan.id+'">'+plan.name+'</option>').join("")+'<option value="CUSTOM">Индивидуальная конфигурация</option></select></label><label>Имя<input name="name" placeholder="Ваше имя" required maxlength="80"></label><label>Контакт для связи<input name="contact" placeholder="Телефон, Telegram или email" required maxlength="120"></label><label>Количество компьютеров<input name="seats" type="number" min="1" max="50" value="1" required></label><button class="button button-red" type="submit">Подготовить заявку менеджеру ↗</button><p class="form-hint">Форма не отправляет данные на сервер. Она готовит текст и JSON-заявку для передачи менеджеру.</p></form></div></section>'+contact()+'</main>';
}
function toast(text){let el=document.querySelector(".site-toast");if(!el){el=document.createElement("div");el.className="site-toast";document.body.appendChild(el)}el.textContent=text;el.classList.add("show");clearTimeout(el.timer);el.timer=setTimeout(()=>el.classList.remove("show"),3000)}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast("Текст обращения скопирован.")}catch(e){const a=document.createElement("textarea");a.value=text;a.style.position="fixed";a.style.opacity="0";document.body.appendChild(a);a.select();const ok=document.execCommand("copy");a.remove();toast(ok?"Текст обращения скопирован.":"Не удалось скопировать текст.")}}
function setupForms(){
  document.querySelectorAll("#contact-form,#tariff-form").forEach(form=>form.addEventListener("submit",async event=>{
    event.preventDefault();
    const data=new FormData(form);
    let message=["Обращение по программе СКОЛ",...Array.from(data.entries()).map(([key,value])=>key+": "+String(value).trim())].join("\\n");
    if(form.id==="tariff-form"){
      const request=createTariffLicenseRequest(form);
      message+="\\n\\nJSON-КОНФИГУРАЦИЯ ДЛЯ LICENSE MANAGER\\n"+JSON.stringify(request,null,2);
    }
    await copyText(message);
    const hint=form.querySelector(".form-hint");
    if(hint)hint.textContent=form.id==="tariff-form"?"Текст обращения и структура выбранной лицензии скопированы. Для импорта также можно скачать JSON выше.":"Текст скопирован. Передайте его менеджеру по согласованному каналу связи.";
  }));
  document.querySelectorAll("[data-plan]").forEach(button=>button.addEventListener("click",()=>{const select=document.querySelector("#plan-select");if(select)select.value=button.dataset.plan}));
}
function setupHomeInteractions(){document.querySelectorAll("[data-home-folder]").forEach(card=>{const trigger=card.querySelector(".home-folder-trigger,.home-pillar-trigger");if(!trigger)return;trigger.addEventListener("click",()=>{const open=card.classList.toggle("is-open");trigger.setAttribute("aria-expanded",String(open));if(trigger.classList.contains("home-folder-trigger"))trigger.setAttribute("aria-label",open?"Закрыть папку продукта СКОЛ CRM":"Открыть папку продукта СКОЛ CRM")})})}
function setupCatalogFolders(){document.querySelectorAll("[data-catalog-folder]").forEach(card=>{const trigger=card.querySelector(".folder-trigger");if(!trigger)return;trigger.addEventListener("click",()=>{const open=card.classList.toggle("is-open");trigger.setAttribute("aria-expanded",String(open));trigger.setAttribute("aria-label",open?"Закрыть папку продукта СКОЛ CRM":"Открыть папку продукта СКОЛ CRM")})})}
